    fn from(value: TimeEntry) -> Self {
        NetworkTimeEntry {
            id: value.id,
            description: value.description.to_string(),
            start: value.start,
            stop: value.stop,
            duration: value.duration,
            billable: value.billable,
            workspace_id: value.workspace_id,
            tags: if value.tags.is_empty() {
